// BlackoutRecovery Blackout recovery of the v2 renderer. While the avatar listens, it
// screens each generated chunk for a fade to black (or fully black
// frames) and shows a healthy listening clip in place of a failed one,
// returning to live frames on the first healthy chunk. On by default.
// Send only the settings to change; an absent or null one keeps its
// current value (on create: its default). Ignored for v1 avatars (the
// setting exists only on the v2 renderer): nothing is stored and the
// rest of the request behaves as without it. It changes how sessions
// render, never the avatar's build: no candidate is captured or
// cancelled. A change applies from the next session.
type BlackoutRecovery struct {
	// Detection How a fade is detected. `tiles` (default, recommended) compares an
	// 8x8 grid of tiles over the whole frame with the recent healthy
	// frames and fires when three quarters of the lit tiles darken
	// together; dark hair, fur or clothes do not set it off. `regions`
	// compares four fixed boxes (face, chest, two torso boxes) and
	// fires when two of them darken together. `both` runs the two and
	// fires when either does.
	Detection *BlackoutRecoveryDetection `json:"detection,omitempty"`

	// Enabled Turn recovery on or off. Default true.
	Enabled *bool `json:"enabled,omitempty"`

	// RegionThreshold The region screen's threshold (`regions`, `both`), read the same
	// way. Strictly between 0 and 1; default 0.20.
	RegionThreshold *float64 `json:"regionThreshold,omitempty"`

	// TileThreshold The tile screen's threshold (`tiles`, `both`): how far, as a
	// fraction of the reference brightness, the tiles must darken for
	// three frames in a row before a chunk counts as fading. Lower is
	// more sensitive (catches shallower fades, and more false alarms).
	// Strictly between 0 and 1; default 0.40.
	TileThreshold *float64 `json:"tileThreshold,omitempty"`
}

